/** Tier-1 starting equipment (character creation only offers tier 1). */
export const PRIMARY_WEAPONS: WeaponDef[] = ALL_PRIMARY_WEAPONS.filter((w) => w.tier === 1);
export const SECONDARY_WEAPONS: WeaponDef[] = ALL_SECONDARY_WEAPONS.filter((w) => w.tier === 1);
export const TIER1_ARMOR: ArmorDef[] = ALL_ARMOR.filter((a) => a.tier === 1);

export const ALL_WEAPONS: WeaponDef[] = [...ALL_PRIMARY_WEAPONS, ...ALL_SECONDARY_WEAPONS];

export function weaponById(id: string): WeaponDef | undefined {
  return ALL_WEAPONS.find((w) => w.id === id);
}
export function armorById(id: string): ArmorDef | undefined {
  return ALL_ARMOR.find((a) => a.id === id);
}
